void rounded(Graphics& g,RectF r,Color c,float radius) { radius=std::min(radius,std::min(r.Width,r.Height)/2); float d=radius*2; GraphicsPath p; p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.GetRight()-d,r.Y,d,d,270,90);p.AddArc(r.GetRight()-d,r.GetBottom()-d,d,d,0,90);p.AddArc(r.X,r.GetBottom()-d,d,d,90,90);p.CloseFigure();SolidBrush b(c);g.FillPath(&b,&p); }
void txt(Graphics& g,const std::wstring& s,RectF r,float size=16,Color c=white,bool bold=false,StringAlignment align=StringAlignmentNear) { FontFamily f(L"Segoe UI Variable"),fallback(L"Segoe UI");Font font(f.IsAvailable()?&f:&fallback,size,bold?FontStyleBold:FontStyleRegular,UnitPixel);StringFormat fmt;fmt.SetAlignment(align);fmt.SetLineAlignment(StringAlignmentCenter);fmt.SetTrimming(StringTrimmingEllipsisCharacter);SolidBrush b(c);g.DrawString(s.c_str(),-1,&font,r,&fmt,&b); }
