void ring(Graphics& g,float x,float y,float d,float value,float stroke=9) {Pen a(ctrl,stroke),b(blue,stroke);a.SetStartCap(LineCapRound);a.SetEndCap(LineCapRound);b.SetStartCap(LineCapRound);b.SetEndCap(LineCapRound);g.DrawEllipse(&a,x+stroke/2,y+stroke/2,d-stroke,d-stroke);if(value>0)g.DrawArc(&b,x+stroke/2,y+stroke/2,d-stroke,d-stroke,-90,360*std::clamp(value,0.f,1.f));}
std::wstring timeNow(){SYSTEMTIME t{};GetLocalTime(&t);wchar_t s[20];swprintf_s(s,L"%d:%02d",t.wHour%12?t.wHour%12:12,t.wMinute);return s;}
std::wstring dateNow(){SYSTEMTIME t{};GetLocalTime(&t);wchar_t s[80]{};GetDateFormatEx(LOCALE_NAME_USER_DEFAULT,0,&t,L"ddd, MMM d",s,80,nullptr);return s;}
std::wstring battery(){SYSTEM_POWER_STATUS p{};if(!GetSystemPowerStatus(&p)||(p.BatteryFlag&128)||p.BatteryLifePercent>100)return L"AC power";return std::to_wstring(p.BatteryLifePercent)+L"%"+(p.ACLineStatus==1?L" · Charging":L"");}
std::wstring timerText(){wchar_t s[20];swprintf_s(s,L"%02d:%02d",left/60,left%60);return s;}
void audioRead(){if(endpoint){float v{};BOOL m{};if(SUCCEEDED(endpoint->GetMasterVolumeLevelScalar(&v)))volume=v;if(SUCCEEDED(endpoint->GetMute(&m)))muted=m;}}
void audioInit(){if(endpoint)endpoint->Release();if(device)device->Release();if(en)en->Release();endpoint=nullptr;device=nullptr;en=nullptr;if(SUCCEEDED(CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_ALL,__uuidof(IMMDeviceEnumerator),(void**)&en))&&SUCCEEDED(en->GetDefaultAudioEndpoint(eRender,eConsole,&device)))device->Activate(__uuidof(IAudioEndpointVolume),CLSCTX_ALL,nullptr,(void**)&endpoint);audioRead();}
void save(){WritePrivateProfileStringW(L"Island",L"Idle",std::to_wstring(idle).c_str(),config.c_str());WritePrivateProfileStringW(L"Island",L"Theme",dark?L"1":L"0",config.c_str());WritePrivateProfileStringW(L"Island",L"Clipboard",clipOn?L"1":L"0",config.c_str());WritePrivateProfileStringW(L"Island",L"Position",std::to_wstring(pos).c_str(),config.c_str());WritePrivateProfileStringW(L"Island",L"Monitor",std::to_wstring(monitor).c_str(),config.c_str());}
